g.bounds = function (shape, selector) {
     var bounds, bx, by, bw, bh;
     bounds = shape.bounds();
if (selector === 'x') {
     var bx = bounds.x;
     return bx;
  }
if (selector === 'y') {
     var by = bounds.y;
     return by;
  }
if (selector === 'w') {
     var bw = bounds.width;
     return bw;
  }
if (selector === 'h') {
     var bh = bounds.height;
     return bh;
  }
if (selector === 'point') {
     var bx = bounds.x;
     var by = bounds.y;
     return new g.Point(bx,by);
  }
};

