g.importSVG = function (file) {
    var parser, xmlDoc;
    var svgString = ndbx.findAsset(file);
    if (window.DOMParser) {
        parser = new DOMParser();
        xmlDoc = parser.parseFromString(svgString, "image/svg+xml");
    } else { // Internet Explorer
        xmlDoc = new ActiveXObject("Microsoft.XMLDOM");
        xmlDoc.async = false;
        xmlDoc.loadXML(svgString);
    }
    return g.svg.interpret(xmlDoc.documentElement);
};

functions.ref:
Generate a visual link between two shapes.

    var r1 = g.rect({x: -75, y: -50}, 1, 20);
    var r2 = g.rect({x: 75, y: 30}, 1, 80);
    g.link(r1, r2, 'horizontal');

Note that the original shapes are not included: they just serve as reference templates for creating the link shape. Use `g.merge` if you want to combine everything together:

    var r1 = g.rect({x: -75, y: -50}, 5, 20);
    r1 = g.colorize(r1, 'red');
    var r2 = g.rect({x: 75, y: 30}, 5, 80);
    r2 = g.colorize(r2, 'blue');
    var l = g.link(r1, r2, 'horizontal');
    g.merge(r1, r2, l);


## Parameters
- `shape1`: The first bounding volume of the link shape.
- `shape2`: The second bounding volume of the link.
- `orientation`: The direction of the link shape, either `horizontal` or `vertical`.

Distribute points along a shape.

    var e = g.ellipse({x: 0, y: 0}, 100, 100);
    g.resample(e, 'amount', null, 14, false);

This function recalculates new line segments along the outline of the original shape. This can be used to change the points afterwards:

    var e = g.ellipse({x: 0, y: 0}, 100, 100);
    var r = g.resample(e, 'amount', null, 100, false);
    g.wiggle(r, 'points', {x: 5, y: 5}, 0);

## Parameters
- `shape`: The input shape.
- `method`: The method of distribution (`length` or `amount`).

Argument length: The maximum length of each segment.

Argument points: The amount of output points.

Argument perContour: Boolean, if true, the given amount is per contour, not for the whole path.

Resize the shape by scaling it.

    var r = g.rect({x: 0, y: 0}, 100, 100);
    g.scale(r, {x: 10, y: 50}, {x: 0, y: 0});

Note that scale values are in percentages, so a scale of `20` is 20% of the original shape:

    var r = g.rect({x: 0, y: 0}, 100, 100);
    g.scale(r, 20);

## Parameters
- `shape`: The input shape.
- `scale`: The scale factor, as a point.
- `origin`: The point around which to scale (default = 0,0).

Sort points or shapes using different sorting methods.

    var points = g.grid(6, 4, 200, 100, {x: 0, y: 0});
    g.sort(points, 'distance', {x: 0, y: 0});

Sorted points look just the same as ordinary points. It's only when you *do* something related to the ordering that you see a visible difference:

    var points = g.grid(6, 4, 200, 100, {x: 0, y: 0});
    var sorted = g.sort(points, 'distance', {x: 0, y: 0});
    sorted.map(function (pt, i) {
        return g.ellipse(pt, i + 2, i + 2);
    });

## Parameters
- `shapes`: The list of shapes or points to sort.
- `orderBy`: The sort method (`x`, `y`, `distance` or `angle`).
- `position`: The center point used for `distance` or `angle` sorting.

Arrange shapes in a horizontal or vertical layout.

    var r1 = g.rect({x: 0, y: 0}, 20, 20);
    var r2 = g.rect({x: 0, y: 0}, 30, 30);
    g.stack([r1, r2], 's', 10);

Note that the first element is always moved to the center point (0,0).

## Parameters
- `shapes`: A list of input shapes.
- `direction`: The layout direction, either north (`n`), south (`s`), east (`e`) or west (`w`).
- `margin`: The spacing between each of the shapes.

