g.toPoints = function (shape) {
   var points = [];
  if(shape.segments){
   for (var i = 0; i < shape.segments.length; i += 1) {
     var seg = shape.segments[i];
     if (seg.point) {
         points.push(new g.Point(seg.point.x, seg.point.y));
     }
   }
}
   return points;
};

